(* [comment removed for export] *)
Fixpoint dest2 (ws chs : list word) (nf cb : Z) (i : nat) : list word :=
  match i with
  | O => ws
  | S j => upd (dest2 ws chs nf cb j) (Z.to_nat nf + j) (sx32 (nth (Z.to_nat cb + j) chs (Z_to_bv 64 0)))
  end.

